/* wander 目标位置（屏幕坐标），pet_anim_cb 渐进移动用 */
static lv_coord_t g_wander_target_x = 0;
static lv_coord_t g_wander_base_y = 0;    /* 容器原始 y，弹跳以此为基准不漂移 */
static bool       g_wander_inited = false;

static void pet_anim_cb(lv_timer_t *t)
{
    (void)t;
    if (!g_cur_behavior || !g_body) return;

    g_tick++;

    /* 精灵帧切换：每 3 个 anim tick 切一帧（4帧循环） */
    int frame_idx = (g_tick / 3) % PET_FRAMES_PER_STATE;
    const lv_image_dsc_t *frame = g_cat_frames[g_state].frames[frame_idx];
    if (frame)
        lv_image_set_src(g_body, frame);

    /* ── 位移效果（基于原始位置做偏移，不累加漂移）── */

    /* 初始化 wander 基准位置 */
    if (!g_wander_inited)
    {
        g_wander_target_x = lv_obj_get_x(g_cont);
        g_wander_base_y   = lv_obj_get_y(g_cont);
        g_wander_inited   = true;
    }

    if (g_state == PET_STATE_WANDER || g_state == PET_STATE_IDLE)
    {
        /* 每隔一段时间选新目标 x（屏幕范围内随机） */
        if (g_tick % 20 == 0)
        {
            lv_coord_t sw = lv_display_get_horizontal_resolution(NULL);
            lv_coord_t cont_w = lv_obj_get_width(g_cont);
            g_wander_target_x = rand_range(cont_w / 2, sw - cont_w / 2);
        }
        /* 渐进移动（每 tick 移 2px 趋向目标） */
        lv_coord_t cur_x = lv_obj_get_x(g_cont);
        if (cur_x < g_wander_target_x - 2)
            lv_obj_set_x(g_cont, cur_x + 2);
        else if (cur_x > g_wander_target_x + 2)
            lv_obj_set_x(g_cont, cur_x - 2);
        /* y 保持基准 */
        lv_obj_set_y(g_cont, g_wander_base_y);
    }
    else if (g_state == PET_STATE_PLAY)
    {
        /* 弹跳：基于原始 y 做±12px 偏移，不累加 */
        int off = (g_tick % 2) ? -12 : 12;
        lv_obj_set_y(g_cont, g_wander_base_y + off);
    }
    else if (g_state == PET_STATE_CELEBRATE)
    {
        /* 庆祝弹跳：基于原始 y 做±18px 偏移 */
        int off = (g_tick % 2) ? -18 : 18;
        lv_obj_set_y(g_cont, g_wander_base_y + off);
    }
    else
    {
        /* 其他状态：回到基准位置 */
        lv_obj_set_y(g_cont, g_wander_base_y);
    }
}

